int process_component(mif_hdr_t *hdr, char *buf) {
    mif_component_t component;
    tv_parser_t parser;

    // Initialize component structure
    component_init(&component);

    // Initialize TV parser
    tv_parser_init(&parser);

    // Parse buffer for component attributes
    if (tv_parser_parse(&parser, buf) != 0) {
        return -1;
    }

    if (!tv_parser_get_value(&parser, "top-left-x", &component.top_left_x)) {
        return -1;
    }

    if (!tv_parser_get_value(&parser, "top-left-y", &component.top_left_y)) {
        return -1;
    }

    if (!tv_parser_get_value(&parser, "width", &component.width)) {
        return -1;
    }

    if (!tv_parser_get_value(&parser, "height", &component.height)) {
        return -1;
    }

    if (!tv_parser_get_value(&parser, "sample-rate", &component.sample_rate)) {
        return -1;
    }

    if (!tv_parser_get_value(&parser, "precision", &component.precision)) {
        return -1;
    }

    if (!tv_parser_get_value(&parser, "sign", &component.sign)) {
        return -1;
    }

    if (!tv_parser_get_value(&parser, "data", &component.data)) {
        return -1;
    }

    // Add the component to the header
    if (hdr->add_component(hdr, &component) != 0) {
        return -1;
    }

    return 0;
}

int process_mif_component(mif_hdr_t *hdr, char *buf) {
    mif_comp_t comp;
    tv_parser_t parser;
    int ret = -1;

    // Initialize component
    memset(&comp, 0, sizeof(comp));

    // Initialize TV parser
    tv_parser_init(&parser, buf);

    // Parse attributes
    comp.x = tv_parser_get_int(&parser, "TOP_X", -1);
    comp.y = tv_parser_get_int(&parser, "TOP_Y", -1);
    comp.width = tv_parser_get_int(&parser, "WIDTH", -1);
    comp.height = tv_parser_get_int(&parser, "HEIGHT", -1);
    comp.xsample = tv_parser_get_int(&parser, "XSAMPLE_RATE", -1);
    comp.ysample = tv_parser_get_int(&parser, "YSAMPLE_RATE", -1);
    comp.precision = tv_parser_get_int(&parser, "PRECISION", -1);
    comp.sign = tv_parser_get_int(&parser, "SIGN", -1);
    comp.data = tv_parser_get_string(&parser, "DATA", NULL);

    if (comp.x == -1 || comp.y == -1 || comp.width == -1 || comp.height == -1 ||
        comp.xsample == -1 || comp.ysample == -1 || comp.precision == -1 ||
        comp.sign == -1 || comp.data == NULL) {
        goto cleanup;
    }

    if (mif_add_component(hdr, &comp) != 0) {
        goto cleanup;
    }

    ret = 0;

cleanup:
    tv_parser_destroy(&parser);
    return ret;
}

