int process_mif_component(mif_hdr_t *hdr, char *buf) {
    mif_component_t comp;
    tv_parser_t parser;
    int ret = -1;

    mif_tv_parser_init(&parser, buf);

    comp.x = mif_tv_parser_get_int(&parser, "TLX");
    comp.y = mif_tv_parser_get_int(&parser, "TLY");
    comp.width = mif_tv_parser_get_int(&parser, "WIDTH");
    comp.height = mif_tv_parser_get_int(&parser, "HEIGHT");
    comp.sample_rate_x = mif_tv_parser_get_int(&parser, "SRX");
    comp.sample_rate_y = mif_tv_parser_get_int(&parser, "SRY");
    comp.precision = mif_tv_parser_get_int(&parser, "PREC");
    comp.sign = mif_tv_parser_get_int(&parser, "SIGN");

    if (comp.x == INT_MIN || comp.y == INT_MIN || comp.width == INT_MIN ||
        comp.height == INT_MIN || comp.sample_rate_x == INT_MIN ||
        comp.sample_rate_y == INT_MIN || comp.precision == INT_MIN ||
        comp.sign == INT_MIN) {
        goto cleanup;
    }

    comp.data = mif_tv_parser_get_data(&parser);
    if (!comp.data) {
        goto cleanup;
    }

    if (mif_component_create(hdr, &comp) != 0) {
        goto cleanup;
    }

    ret = 0;

cleanup:
    mif_tv_parser_cleanup(&parser);
    return ret;
}

int process_mif_component(mif_hdr_t *hdr, char *buf) {
    mif_comp_t comp;
