        return -1;
    }
    if (!tv_parser_get_int(&parser, "WIDTH", &comp.width)) {
        return -1;
    }
    if (!tv_parser_get_int(&parser, "HEIGHT", &comp.height)) {
        return -1;
    }
    if (!tv_parser_get_int(&parser, "X_RATE", &comp.x_rate)) {
        return -1;
    }
    if (!tv_parser_get_int(&parser, "Y_RATE", &parser, &comp.y_rate)) {
        return -1;
    }
    if (!tv_parser_get_int(&parser, "PRECISION", &comp.precision)) {
        return -1;
    }
